#!/usr/bin/env bash

set -Eeuo pipefail

# The official PostgreSQL image starts a temporary server while it runs the
# numbered init scripts. Those WAL files are not part of the initialized
# recovery history yet; acknowledge them until the wrapper has created and
# checked the pgBackRest stanza. All WAL generated by the long-running server
# is archived through pgBackRest.
if [[ ! -f /var/lib/postgresql/data/.pgbackrest-stanza-ready ]]; then
  exit 0
fi

exec pgbackrest --stanza=civil-atlas archive-push "$1"
